import{_ as l,a0 as n,w as d,s as r,I as i,x as e,a1 as t,A as o,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"怎樣在桌面上安裝 Docker CE？ | LCTT x X-CMD","titleTemplate":false,"description":"怎樣在桌面上安裝 Docker CE？ | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣在桌面上安裝 Docker CE？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣在桌面上安裝 Docker CE？ | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180108 How to Install Docker CE on Your Desktop","title":"怎樣在桌面上安裝 Docker CE？","tag":"201806","desc":""},"relativePath":"201806/20180108 How to Install Docker CE on Your Desktop.md","filePath":"[post].md"}'),c={name:"201806/20180108 How to Install Docker CE on Your Desktop.md"};function k(h,s,g,u,b,f){const a=n("Link");return d(),r("div",null,[s[17]||(s[17]=i("h1",{id:"怎樣在桌面上安裝-docker-ce",tabindex:"-1"},[e("怎樣在桌面上安裝 Docker CE？ "),i("a",{class:"header-anchor",href:"#怎樣在桌面上安裝-docker-ce","aria-label":"Permalink to “怎樣在桌面上安裝 Docker CE？”"},"​")],-1)),s[18]||(s[18]=i("blockquote",null,[i("p",null,"按照這些簡單的步驟在你的 Linux、Mac 或 Windows 桌面上安裝 Docker CE。")],-1)),s[19]||(s[19]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/containers-volumes_0.jpg?itok=gv0_MXiZ",alt:""})],-1)),i("p",null,[t(a,{href:"https://www.linux.com/blog/intro-to-linux/2017/12/container-basics-terms-you-need-know"},{default:o(()=>[...s[0]||(s[0]=[e("在上一篇文章中",-1)])]),_:1}),s[1]||(s[1]=e("，我們學習了容器世界的一些基本術語。當我們運行命令並在後續文章中使用其中一些術語時，這些背景信息將會派上用場，包括這篇文章。本文將介紹在桌面 Linux、 macOS 和 Windows 上安裝 Docker，它適用於想要開始使用 Docker 容器的初學者。唯一的先決條件是你對命令列界面滿意。",-1))]),s[20]||(s[20]=p(`<h3 id="為什麼我在本地機器上需要-docker-ce" tabindex="-1">為什麼我在本地機器上需要 Docker CE？ <a class="header-anchor" href="#為什麼我在本地機器上需要-docker-ce" aria-label="Permalink to “為什麼我在本地機器上需要 Docker CE？”">​</a></h3><p>作為一個新用户，你很可能想知道為什麼你在本地系統上需要容器。難道它們不是作為微服務在雲和服務器中運行嗎？儘管容器長期以來一直是 Linux 世界的一部分，但 Docker 才真正使容器的工具和技術步入使用。</p><p>Docker 容器最大的優點是可以使用本地機器進行開發和測試。你在本地系統上創建的容器映像可以在“任何位置”運行。開發人員和操作人員之間不再會為應用程序在開發系統上運行良好但生產環境中出現問題而產生紛爭。</p><p>而這個關鍵是，要創建容器化的應用程序，你必須能夠在本地系統上運行和創建容器。</p><p>你可以使用以下三個平台中的任何一個 —— 桌面 Linux、 Windows 或 macOS 作為容器的開發平台。一旦 Docker 在這些系統上成功運行，你將可以在不同的平台上使用相同的命令。因此，接下來你運行的操作系統無關緊要。</p><p>這就是 Docker 之美。</p><h3 id="讓我們開始吧" tabindex="-1">讓我們開始吧 <a class="header-anchor" href="#讓我們開始吧" aria-label="Permalink to “讓我們開始吧”">​</a></h3><p>現在有兩個版本的 Docker：Docker 企業版（EE）和 Docker 社區版（CE）。我們將使用 Docker 社區版，這是一個免費的 Docker 版本，面向想要開始使用 Docker 的開發人員和愛好者。</p><p>Docker CE 有兩個版本：stable 和 edge。顧名思義，stable（穩定）版本會為你提供經過充分測試的季度更新，而 edge 版本每個月都會提供新的更新。經過進一步的測試之後，這些邊緣特徵將被添加到穩定版本中。我建議新用户使用 stable 版本。</p><p>Docker CE 支持 macOS、 Windows 10、 Ubuntu 14.04/16.04/17.04/17.10、 Debian 7.7/8/9/10、 Fedora 25/26/27 和 CentOS。雖然你可以下載 Docker CE 二進制文件並安裝到桌面 Linux 上，但我建議添加倉庫源以便繼續獲得修補程序和更新。</p><h3 id="在桌面-linux-上安裝-docker-ce" tabindex="-1">在桌面 Linux 上安裝 Docker CE <a class="header-anchor" href="#在桌面-linux-上安裝-docker-ce" aria-label="Permalink to “在桌面 Linux 上安裝 Docker CE”">​</a></h3><p>你不需要一個完整的桌面 Linux 來運行 Docker，你也可以將它安裝在最小的 Linux 服務器上，即你可以在一個虛擬機中運行。在本教程中，我將在我的主系統的 Fedora 27 和 Ubuntu 17.04 上運行它。</p><h3 id="在-ubuntu-上安裝" tabindex="-1">在 Ubuntu 上安裝 <a class="header-anchor" href="#在-ubuntu-上安裝" aria-label="Permalink to “在 Ubuntu 上安裝”">​</a></h3><p>首先，運行系統更新，以便你的 Ubuntu 軟件包完全更新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get update</span></span></code></pre></div><p>現在運行系統升級：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get dist-upgrade</span></span></code></pre></div><p>然後安裝 Docker PGP 密鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository &quot;deb [arch=amd64] https://download.docker.com/linux/ubuntu $(lsb_release -cs) stable&quot;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Update the repository info again:</span></span>
<span class="line"><span>$ sudo apt-get update</span></span></code></pre></div><p>現在安裝 Docker CE：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install docker-ce</span></span></code></pre></div><p>一旦安裝完成，Docker CE 就會在基於 Ubuntu 的系統上自動運行，讓我們來檢查它是否在運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status docker</span></span></code></pre></div><p>你應該得到以下輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker.service - Docker Application Container Engine</span></span>
<span class="line"><span>  Loaded: loaded (/lib/systemd/system/docker.service; enabled; vendor preset: enabled)</span></span>
<span class="line"><span>  Active: active (running) since Thu 2017-12-28 15:06:35 EST; 19min ago</span></span>
<span class="line"><span>    Docs: https://docs.docker.com</span></span>
<span class="line"><span>Main PID: 30539 (dockerd)</span></span></code></pre></div><p>由於 Docker 安裝在你的系統上，你現在可以使用 Docker CLI（命令列界面）運行 Docker 命令。像往常一樣，我們運行 ‘Hello World’ 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run hello-world</span></span></code></pre></div><p><img src="https://lh5.googleusercontent.com/YMChR_7xglpYBT91rtXnqQc6R1Hx9qMX_iO99vL8Z8C0-BlynDcL5B5pG-zzH0fKU0Qvnzd89v0KDEbZiO0gTfGNGfDtO-FkTt0bmzIQ-TKbNmv18S9RXdkSeXqgKDFRewnaHPj2" alt="YMChR_7xglpYBT91rtXnqQc6R1Hx9qMX_iO99vL8"></p><p>恭喜！在你的 Ubuntu 系統上正在運行着 Docker。</p><h3 id="在-fedora-上安裝-docker-ce" tabindex="-1">在 Fedora 上安裝 Docker CE <a class="header-anchor" href="#在-fedora-上安裝-docker-ce" aria-label="Permalink to “在 Fedora 上安裝 Docker CE”">​</a></h3><p>Fedora 27 上的情況有些不同。在 Fedora 上，你首先需要安裝 <code>def-plugins-core</code> 包，這將允許你從 CLI 管理你的 DNF 包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf -y install dnf-plugins-core</span></span></code></pre></div><p>現在在你的系統上安裝 Docker 倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf config-manager \\</span></span>
<span class="line"><span>    --add-repo \\</span></span>
<span class="line"><span>    https://download.docker.com/linux/fedora/docker-ce.repo</span></span>
<span class="line"><span>It’s time to install Docker CE:</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install docker-ce</span></span></code></pre></div><p>與 Ubuntu 不同，Docker 不會在 Fedora 上自動啓動。那麼讓我們啓動它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl start docker</span></span></code></pre></div><p>你必須在每次重新啓動後手動啓動 Docker，因此讓我們將其配置為在重新啓動後自動啓動。<code>$ systemctl enable docker</code> 就行。現在該運行 Hello World 命令了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run hello-world</span></span></code></pre></div><p>恭喜，在你的 Fedora 27 系統上正在運行着 Docker。</p><h3 id="解除-root" tabindex="-1">解除 root <a class="header-anchor" href="#解除-root" aria-label="Permalink to “解除 root”">​</a></h3><p>你可能已經注意到你必須使用 <code>sudo</code> 來運行 <code>docker</code> 命令。這是因為 Docker 守護進程與 UNIX 套接字綁定，而不是 TCP 端口，套接字由 root 用户擁有。所以，你需要 <code>sudo</code> 權限才能運行 <code>docker</code> 命令。你可以將系統用户添加到 docker 組，這樣它就不需要 <code>sudo</code> 了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo groupadd docker</span></span></code></pre></div><p>在大多數情況下，在安裝 Docker CE 時會自動創建 Docker 用户組，因此你只需將用户添加到該組中即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -aG docker $USER</span></span></code></pre></div><p>為了測試該組是否已經成功添加，根據用户名運行 <code>groups</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ groups swapnil</span></span></code></pre></div><p>（這裏，<code>swapnil</code> 是用户名。）</p><p>這是在我係統上的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>swapnil : swapnil adm cdrom sudo dip plugdev lpadmin sambashare docker</span></span></code></pre></div><p>你可以看到該用户也屬於 docker 組。註銷系統，這樣組就會生效。一旦你再次登錄，在不使用 <code>sudo</code> 的情況下試試 Hello World 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker run hello-world</span></span></code></pre></div><p>你可以通過運行以下命令來查看關於 Docker 的安裝版本以及更多系統信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker info</span></span></code></pre></div><h3 id="在-macos-和-windows-上安裝-docker-ce" tabindex="-1">在 macOS 和 Windows 上安裝 Docker CE <a class="header-anchor" href="#在-macos-和-windows-上安裝-docker-ce" aria-label="Permalink to “在 macOS 和 Windows 上安裝 Docker CE”">​</a></h3><p>你可以在 macOS 和 Windows 上很輕鬆地安裝 Docker CE（和 EE）。下載官方為 macOS 提供的 Docker 安裝包，在 macOS 上安裝應用程序的方式是隻需將它們拖到 Applications 目錄即可。一旦文件被複制，從 spotlight（LCTT 譯註：mac 下的搜索功能）下打開 Docker 開始安裝。一旦安裝，Docker 將自動啓動，你可以在 macOS 的頂部看到它。</p><p><img src="https://lh3.googleusercontent.com/IEX23j65zYlF8mZ1c-T_vFw_i1B1T1hibw_AuhEAfwv9oFpMfcAqkgEk7K5o58iDAAfGozSpIvY_qEsTOHRlSbesMKwTnG9rRkWba1KPSmnuH1LyoccDGNO3Clbz8du0gSByZxNj" alt="IEX23j65zYlF8mZ1c-T_vFw_i1B1T1hibw_AuhEA"></p><p>macOS 是類 UNIX 系統，所以你可以簡單地打開終端應用程序，並開始使用 Docker 命令。測試 hello world 應用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker run hello-world</span></span></code></pre></div><p>恭喜，你已經在你的 macOS 上運行了 Docker。</p><h3 id="在-windows-10-上安裝-docker" tabindex="-1">在 Windows 10 上安裝 Docker <a class="header-anchor" href="#在-windows-10-上安裝-docker" aria-label="Permalink to “在 Windows 10 上安裝 Docker”">​</a></h3><p>你需要最新版本的 Windows 10 Pro 或 Server 才能在它上面安裝或運行 Docker。如果你沒有完全更新，Windows 將不會安裝 Docker。我在 Windows 10 系統上遇到了錯誤，必須運行系統更新。我的版本還很落後，我出現了[這個][14] bug。所以，如果你無法在 Windows 上安裝 Docker，只要知道並不是只有你一個。仔細檢查該 bug 以找到解決方案。</p><p>一旦你在 Windows 上安裝 Docker 後，你可以通過 WSL 使用 bash shell，或者使用 PowerShell 來運行 Docker 命令。讓我們在 PowerShell 中測試 “Hello World” 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PS C:\\Users\\swapnil&gt; docker run hello-world</span></span></code></pre></div><p>恭喜，你已經在 Windows 上運行了 Docker。</p><p>在下一篇文章中，我們將討論如何從 DockerHub 中拉取鏡像並在我們的系統上運行容器。我們還會討論推送我們自己的容器到 Docker Hub。</p><hr>`,68)),i("p",null,[s[3]||(s[3]=e("via: ",-1)),t(a,{href:"https://www.linux.com/blog/learn/intro-to-linux/how-install-docker-ce-your-desktop"},{default:o(()=>[...s[2]||(s[2]=[e("https://www.linux.com/blog/learn/intro-to-linux/how-install-docker-ce-your-desktop",-1)])]),_:1})]),i("p",null,[s[8]||(s[8]=e("作者：",-1)),t(a,{href:"https://www.linux.com/users/arnieswap"},{default:o(()=>[...s[4]||(s[4]=[e("SWAPNIL BHARTIYA",-1)])]),_:1}),s[9]||(s[9]=e(" 選題：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[5]||(s[5]=[e("lujun9972",-1)])]),_:1}),s[10]||(s[10]=e(" 譯者：",-1)),t(a,{href:"https://github.com/MjSeven"},{default:o(()=>[...s[6]||(s[6]=[e("MjSeven",-1)])]),_:1}),s[11]||(s[11]=e(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:o(()=>[...s[7]||(s[7]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[14]||(s[14]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[12]||(s[12]=[e("LCTT",-1)])]),_:1}),s[15]||(s[15]=e(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:o(()=>[...s[13]||(s[13]=[e("Linux中國",-1)])]),_:1}),s[16]||(s[16]=e(" 榮譽推出",-1))])])}const y=l(c,[["render",k]]);export{D as __pageData,y as default};
